# Run on a qualified Windows x64/MSVC host, under the approved current user.
# No private key/password is accepted on the command line or generated by this script.
param([Parameter(Mandatory=$true)][string]$CertificateThumbprint,
      [Parameter(Mandatory=$true)][string]$TimestampUrl)
$ErrorActionPreference = "Stop"
if (-not $IsWindows) { throw "A qualified native Windows PowerShell 7 host is required." }
if ($CertificateThumbprint -notmatch '^[0-9A-Fa-f]{40}$') { throw "Supply the approved certificate thumbprint." }
if (-not $TimestampUrl.StartsWith('https://')) { throw "An approved HTTPS RFC3161 timestamp service is required." }
$Root = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
Set-Location $Root
python scripts/release/check_release.py
if ($LASTEXITCODE -ne 0) { throw "Release evidence gate is blocked. No signing was attempted." }
if ($env:NARADA_DEV_VAULT_KEY -or $env:NARADA_DEV_TOKEN) { throw "Development vault/preview variables must not enter a release build." }
$Cert = Get-Item "Cert:\CurrentUser\My\$CertificateThumbprint"
if (-not $Cert.HasPrivateKey -or $Cert.NotAfter -le (Get-Date)) { throw "The approved private signing key is unavailable or expired." }
$SignTool = (Get-Command signtool.exe -ErrorAction Stop).Source
node scripts/prepare-sidecar.mjs
if ($LASTEXITCODE -ne 0) { throw "Default-feature sidecar build failed." }
$Sidecar = Join-Path $Root 'apps/desktop-shell/src-tauri/binaries/narada-agent-x86_64-pc-windows-msvc.exe'
& $SignTool sign /sha1 $CertificateThumbprint /s My /fd SHA256 /tr $TimestampUrl /td SHA256 $Sidecar
if ($LASTEXITCODE -ne 0) { throw "Sidecar signing failed." }
$ConfigDir = Join-Path $Root '.cache/release-signing'; New-Item -ItemType Directory -Force $ConfigDir | Out-Null
$Config = Join-Path $ConfigDir 'native-signing.json'
@{ bundle = @{ windows = @{ certificateThumbprint = $CertificateThumbprint; digestAlgorithm = 'sha256'; timestampUrl = $TimestampUrl; tsp = $true } } } | ConvertTo-Json -Depth 6 | Set-Content -Encoding utf8 $Config
try {
  Push-Location (Join-Path $Root 'apps/desktop-shell')
  npx tauri build --config $Config
  if ($LASTEXITCODE -ne 0) { throw "Native bundle/signing failed." }
} finally { Pop-Location; Remove-Item $Config -ErrorAction SilentlyContinue }
$Installers = Get-ChildItem (Join-Path $Root 'target/release/bundle/nsis') -Filter '*.exe'
if (-not $Installers) { throw "No installer was produced." }
foreach ($File in @($Sidecar) + @($Installers.FullName)) {
  $Signature = Get-AuthenticodeSignature $File
  if ($Signature.Status -ne 'Valid' -or $Signature.SignerCertificate.Thumbprint -ne $CertificateThumbprint) { throw "Wrong or invalid Authenticode signature: $File" }
  & $SignTool verify /pa /all /v $File
  if ($LASTEXITCODE -ne 0) { throw "Native signature verification failed." }
  Get-FileHash -Algorithm SHA256 $File
}
Write-Output "Artifacts were produced and checked on this host. Native installation, update and pilot approval must remain bound to these exact artifact hashes."
